// @generated by `cargo xtask gen-contracts` from contracts/. Do not edit.

//! Every valid fixture in `contracts/fixtures` deserializes into its generated type and
//! serializes back to the same JSON (numbers compared as f64). A valid `extra_` case carries a
//! field its open type does not know and serializes back without it; an invalid `extra_`
//! case is refused by its closed type. Every invalid fixture is checked against the full
//! schema by `cargo xtask contracts`.

use serde::{Serialize, de::DeserializeOwned};
use serde_json::Value;

fn normalize(v: Value) -> Value {
    match v {
        Value::Number(n) => n.as_f64().map_or(Value::Null, |f| serde_json::json!(f)),
        Value::Array(a) => Value::Array(a.into_iter().map(normalize).collect()),
        Value::Object(o) => Value::Object(o.into_iter().map(|(k, v)| (k, normalize(v))).collect()),
        other => other,
    }
}

fn read(rel: &str) -> Value {
    let path = format!(
        "{}/../../contracts/fixtures/{rel}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).expect("fixture is readable");
    serde_json::from_str(&text).expect("fixture is JSON")
}

/// `rel` deserialized into `T` and serialized back, with the fixture.
fn reread<T: Serialize + DeserializeOwned>(rel: &str) -> (Value, Value) {
    let value = read(rel);
    let typed: T = serde_json::from_value(value.clone()).unwrap_or_else(|e| panic!("{rel}: {e}"));
    (
        serde_json::to_value(&typed).expect("type serializes"),
        value,
    )
}

fn roundtrip<T: Serialize + DeserializeOwned>(rel: &str) {
    let (back, value) = reread::<T>(rel);
    assert_eq!(
        normalize(back),
        normalize(value),
        "{rel} does not round-trip"
    );
}

/// `value` without the object keys `back` lacks, at every depth.
fn known(value: Value, back: &Value) -> Value {
    match (value, back) {
        (Value::Object(o), Value::Object(b)) => Value::Object(
            o.into_iter()
                .filter_map(|(k, v)| b.get(&k).map(|bv| (k.clone(), known(v, bv))))
                .collect(),
        ),
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            Value::Array(a.into_iter().zip(b).map(|(v, bv)| known(v, bv)).collect())
        }
        (other, _) => other,
    }
}

fn roundtrip_extra<T: Serialize + DeserializeOwned>(rel: &str) {
    let (back, value) = reread::<T>(rel);
    let kept = known(value.clone(), &back);
    assert_ne!(
        normalize(kept.clone()),
        normalize(value),
        "{rel} has no unknown field"
    );
    assert_eq!(
        normalize(back),
        normalize(kept),
        "{rel} does not round-trip its known fields"
    );
}

fn refused<T: DeserializeOwned>(rel: &str) {
    assert!(
        serde_json::from_value::<T>(read(rel)).is_err(),
        "{rel} is accepted"
    );
}

